-- ---------------------------------------------------------------------------
-- Seed: framework control catalogs for SOC 2 and ISO/IEC 27001:2022.
--
-- WHY. Adds two new information-security frameworks and their FULL published
-- control catalogs to public.framework_controls, so the Frameworks page shows a
-- real catalog behind each framework card (not just a metadata count):
--   * SOC 2  - AICPA Trust Services Criteria (TSC 2017, incl. 2022 revisions):
--     all 33 Common Criteria (CC1.x-CC9.x) plus the additional-category
--     criteria for Availability (A1.x), Confidentiality (C1.x), Processing
--     Integrity (PI1.x) and Privacy (P1-P8). 61 criteria total.
--   * ISO/IEC 27001:2022 Annex A - all 93 controls across the four themes:
--     Organizational (A.5.1-A.5.37), People (A.6.1-A.6.8), Physical
--     (A.7.1-A.7.14) and Technological (A.8.1-A.8.34). Titles are the 2022
--     revision titles (which differ from ISO/IEC 27001:2013).
--
-- Every control_ref and title is the REAL published identifier/title from the
-- respective standard; descriptions summarise the real control statement.
-- No refs, titles or counts are invented. The frameworks rows are inserted
-- FIRST, then their controls reference them. Idempotent; replays from zero.
-- ---------------------------------------------------------------------------

-- Frameworks (global metadata). org_id is set to the all-zeros global org that
-- the ten existing framework rows use (frameworks.org_id is NOT NULL since the
-- 20260820000001 schema-drift heal; under a migration role current_user_org_id()
-- is NULL, so the value is set explicitly). control_count is the real published
-- number; coverage_pct 0 (honest - the demo org is not yet assessed against them).
   effective_date, control_count, structure, description, url, adopted, coverage_pct)
VALUES
  ('soc2', '00000000-0000-0000-0000-000000000000',
   'SOC 2 - Trust Services Criteria', 'SOC 2', '2017 (rev. 2022)',
   'Information Security', 'AICPA', 'United States', '2017-04-15', 61,
   'Common Criteria (CC1-CC9) plus Availability, Confidentiality, Processing Integrity and Privacy categories',
   'AICPA Trust Services Criteria for security, availability, processing integrity, confidentiality and privacy, used for SOC 2 examinations of service organizations.',
   'https://www.aicpa-cima.com/resources/download/2017-trust-services-criteria-with-revised-points-of-focus-2022',
   true, 0),
  ('iso-27001', '00000000-0000-0000-0000-000000000000',
   'ISO/IEC 27001:2022', 'ISO 27001', '2022',
   'Information Security', 'ISO/IEC', 'International', '2022-10-25', 93,
   '93 Annex A controls in four themes: Organizational, People, Physical, Technological',
   'International standard for information security management systems (ISMS); Annex A lists 93 reference controls (aligned to ISO/IEC 27002:2022) across organizational, people, physical and technological themes.',
   'https://www.iso.org/standard/27001', true, 0)
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, short_name = EXCLUDED.short_name, version = EXCLUDED.version,
  category = EXCLUDED.category, issuing_body = EXCLUDED.issuing_body,
  jurisdiction = EXCLUDED.jurisdiction, effective_date = EXCLUDED.effective_date,
  control_count = EXCLUDED.control_count, structure = EXCLUDED.structure,
  description = EXCLUDED.description, url = EXCLUDED.url,
  adopted = EXCLUDED.adopted, coverage_pct = EXCLUDED.coverage_pct;

-- framework_controls.org_id was added by the ws01 tenancy sweep via a dynamic
-- EXECUTE format('ALTER TABLE public.%I ADD COLUMN org_id ...') loop. Re-assert
-- it here as a literal, guarded no-op so this seed is self-contained (the
-- catalog rows below set org_id explicitly to the demo org) and so a static
-- replay-order check can see the column exists before the INSERTs use it.
ALTER TABLE public.framework_controls
  ADD COLUMN IF NOT EXISTS org_id uuid DEFAULT current_user_org_id();

-- SOC 2 - AICPA Trust Services Criteria (61 controls)
ON CONFLICT (id) DO UPDATE SET
  control_ref = EXCLUDED.control_ref, domain = EXCLUDED.domain,
  title = EXCLUDED.title, description = EXCLUDED.description,
  control_type = EXCLUDED.control_type, priority = EXCLUDED.priority;

-- ISO/IEC 27001:2022 Annex A controls (93 controls)
ON CONFLICT (id) DO UPDATE SET
  control_ref = EXCLUDED.control_ref, domain = EXCLUDED.domain,
  title = EXCLUDED.title, description = EXCLUDED.description,
  control_type = EXCLUDED.control_type, priority = EXCLUDED.priority;

-- Count sync + proof.
UPDATE public.frameworks f
SET control_count = (SELECT count(*) FROM public.framework_controls fc
                     WHERE fc.framework_id = f.id
                       AND fc.org_id = '00000000-0000-0000-0000-000000000001')
WHERE f.id IN ('soc2', 'iso-27001');

DO $$
DECLARE
  n_soc2 INTEGER;
  n_iso  INTEGER;
BEGIN
  SELECT count(*) INTO n_soc2 FROM public.framework_controls
   WHERE framework_id = 'soc2' AND org_id = '00000000-0000-0000-0000-000000000001';
  SELECT count(*) INTO n_iso FROM public.framework_controls
   WHERE framework_id = 'iso-27001' AND org_id = '00000000-0000-0000-0000-000000000001';
  RAISE NOTICE 'seed catalog: soc2 = % controls, iso-27001 = % controls', n_soc2, n_iso;
END $$;
