INSERT INTO public.frameworks
  (id, org_id, name, short_name, version, category, issuing_body, jurisdiction,
INSERT INTO public.framework_controls
  (id, org_id, framework_id, control_ref, domain, title, description, control_type, priority)
VALUES
  ('fc-soc2-cc1-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC1.1', 'Control Environment', 'Commitment to integrity and ethical values', 'The entity demonstrates a commitment to integrity and ethical values.', 'governance', 'high'),
  ('fc-soc2-cc1-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC1.2', 'Control Environment', 'Board independence and oversight', 'The board of directors demonstrates independence from management and exercises oversight of the development and performance of internal control.', 'governance', 'high'),
  ('fc-soc2-cc1-3', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC1.3', 'Control Environment', 'Structures, reporting lines, authorities and responsibilities', 'Management establishes, with board oversight, structures, reporting lines, and appropriate authorities and responsibilities in the pursuit of objectives.', 'governance', 'medium'),
  ('fc-soc2-cc1-4', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC1.4', 'Control Environment', 'Commitment to competence', 'The entity demonstrates a commitment to attract, develop, and retain competent individuals in alignment with objectives.', 'governance', 'medium'),
  ('fc-soc2-cc1-5', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC1.5', 'Control Environment', 'Accountability for internal control', 'The entity holds individuals accountable for their internal control responsibilities in the pursuit of objectives.', 'governance', 'medium'),
  ('fc-soc2-cc2-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC2.1', 'Communication and Information', 'Use of relevant, quality information', 'The entity obtains or generates and uses relevant, quality information to support the functioning of internal control.', 'administrative', 'medium'),
  ('fc-soc2-cc2-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC2.2', 'Communication and Information', 'Internal communication of internal control information', 'The entity internally communicates information, including objectives and responsibilities for internal control, necessary to support the functioning of internal control.', 'administrative', 'medium'),
  ('fc-soc2-cc2-3', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC2.3', 'Communication and Information', 'External communication', 'The entity communicates with external parties regarding matters affecting the functioning of internal control.', 'administrative', 'medium'),
  ('fc-soc2-cc3-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC3.1', 'Risk Assessment', 'Objectives specified with sufficient clarity', 'The entity specifies objectives with sufficient clarity to enable the identification and assessment of risks relating to objectives.', 'governance', 'medium'),
  ('fc-soc2-cc3-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC3.2', 'Risk Assessment', 'Identification and analysis of risk', 'The entity identifies risks to the achievement of its objectives across the entity and analyzes risks as a basis for determining how the risks should be managed.', 'governance', 'high'),
  ('fc-soc2-cc3-3', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC3.3', 'Risk Assessment', 'Consideration of fraud risk', 'The entity considers the potential for fraud in assessing risks to the achievement of objectives.', 'detective', 'medium'),
  ('fc-soc2-cc3-4', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC3.4', 'Risk Assessment', 'Identification and assessment of change', 'The entity identifies and assesses changes that could significantly impact the system of internal control.', 'detective', 'medium'),
  ('fc-soc2-cc4-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC4.1', 'Monitoring Activities', 'Ongoing and separate evaluations', 'The entity selects, develops, and performs ongoing and/or separate evaluations to ascertain whether the components of internal control are present and functioning.', 'detective', 'medium'),
  ('fc-soc2-cc4-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC4.2', 'Monitoring Activities', 'Evaluation and communication of deficiencies', 'The entity evaluates and communicates internal control deficiencies in a timely manner to those parties responsible for taking corrective action, including senior management and the board of directors, as appropriate.', 'corrective', 'medium'),
  ('fc-soc2-cc5-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC5.1', 'Control Activities', 'Selection and development of control activities', 'The entity selects and develops control activities that contribute to the mitigation of risks to the achievement of objectives to acceptable levels.', 'preventive', 'medium'),
  ('fc-soc2-cc5-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC5.2', 'Control Activities', 'General control activities over technology', 'The entity also selects and develops general control activities over technology to support the achievement of objectives.', 'technical', 'medium'),
  ('fc-soc2-cc5-3', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC5.3', 'Control Activities', 'Deployment through policies and procedures', 'The entity deploys control activities through policies that establish what is expected and in procedures that put policies into action.', 'administrative', 'medium'),
  ('fc-soc2-cc6-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC6.1', 'Logical and Physical Access Controls', 'Logical access security software and architecture', 'The entity implements logical access security software, infrastructure, and architectures over protected information assets to protect them from security events to meet the entity''''s objectives.', 'technical', 'high'),
  ('fc-soc2-cc6-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC6.2', 'Logical and Physical Access Controls', 'Registration and authorization of new users', 'Prior to issuing system credentials and granting system access, the entity registers and authorizes new internal and external users, and removes credentials when access is no longer authorized.', 'preventive', 'high'),
  ('fc-soc2-cc6-3', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC6.3', 'Logical and Physical Access Controls', 'Role-based access with least privilege', 'The entity authorizes, modifies, or removes access to data, software, functions, and other protected information assets based on roles, responsibilities, or system design, considering least privilege and segregation of duties.', 'preventive', 'high'),
  ('fc-soc2-cc6-4', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC6.4', 'Logical and Physical Access Controls', 'Restriction of physical access', 'The entity restricts physical access to facilities and protected information assets (for example, data center facilities, back-up media storage, and other sensitive locations) to authorized personnel to meet the entity''''s objectives.', 'physical', 'high'),
  ('fc-soc2-cc6-5', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC6.5', 'Logical and Physical Access Controls', 'Secure disposal of physical assets', 'The entity discontinues logical and physical protections over physical assets only after the ability to read or recover data and software from those assets has been diminished and is no longer required to meet the entity''''s objectives.', 'preventive', 'medium'),
  ('fc-soc2-cc6-6', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC6.6', 'Logical and Physical Access Controls', 'Protection against external threats', 'The entity implements logical access security measures to protect against threats from sources outside its system boundaries.', 'preventive', 'high'),
  ('fc-soc2-cc6-7', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC6.7', 'Logical and Physical Access Controls', 'Protection of information in transmission and removal', 'The entity restricts the transmission, movement, and removal of information to authorized internal and external users and processes, and protects it during transmission, movement, or removal to meet the entity''''s objectives.', 'technical', 'high'),
  ('fc-soc2-cc6-8', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC6.8', 'Logical and Physical Access Controls', 'Prevention and detection of unauthorized software', 'The entity implements controls to prevent or detect and act upon the introduction of unauthorized or malicious software to meet the entity''''s objectives.', 'preventive', 'high'),
  ('fc-soc2-cc7-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC7.1', 'System Operations', 'Detection of configuration changes and vulnerabilities', 'To meet its objectives, the entity uses detection and monitoring procedures to identify changes to configurations that result in new vulnerabilities and susceptibilities to newly discovered vulnerabilities.', 'detective', 'high'),
  ('fc-soc2-cc7-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC7.2', 'System Operations', 'Monitoring for anomalies and security events', 'The entity monitors system components and the operation of those components for anomalies indicative of malicious acts, natural disasters, and errors, and analyzes anomalies to determine whether they represent security events.', 'detective', 'high'),
  ('fc-soc2-cc7-3', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC7.3', 'System Operations', 'Evaluation of security events', 'The entity evaluates security events to determine whether they could or have resulted in a failure of the entity to meet its objectives (security incidents) and, if so, takes actions to prevent or address such failures.', 'detective', 'medium'),
  ('fc-soc2-cc7-4', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC7.4', 'System Operations', 'Incident response program', 'The entity responds to identified security incidents by executing a defined incident response program to understand, contain, remediate, and communicate security incidents, as appropriate.', 'corrective', 'high'),
  ('fc-soc2-cc7-5', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC7.5', 'System Operations', 'Recovery from security incidents', 'The entity identifies, develops, and implements activities to recover from identified security incidents.', 'corrective', 'high'),
  ('fc-soc2-cc8-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC8.1', 'Change Management', 'Authorized and tested change management', 'The entity authorizes, designs, develops or acquires, configures, documents, tests, approves, and implements changes to infrastructure, data, software, and procedures to meet its objectives.', 'preventive', 'high'),
  ('fc-soc2-cc9-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC9.1', 'Risk Mitigation', 'Risk mitigation for business disruptions', 'The entity identifies, selects, and develops risk mitigation activities for risks arising from potential business disruptions.', 'corrective', 'medium'),
  ('fc-soc2-cc9-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'CC9.2', 'Risk Mitigation', 'Management of vendor and business partner risk', 'The entity assesses and manages risks associated with vendors and business partners.', 'administrative', 'high'),
  ('fc-soc2-a1-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'A1.1', 'Availability', 'Capacity management', 'The entity maintains, monitors, and evaluates current processing capacity and use of system components to manage capacity demand and to enable the implementation of additional capacity to help meet its objectives.', 'detective', 'medium'),
  ('fc-soc2-a1-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'A1.2', 'Availability', 'Environmental protections, backup and recovery infrastructure', 'The entity authorizes, designs, develops or acquires, implements, operates, approves, maintains, and monitors environmental protections, software, data back-up processes, and recovery infrastructure to meet its objectives.', 'preventive', 'high'),
  ('fc-soc2-a1-3', '00000000-0000-0000-0000-000000000001', 'soc2', 'A1.3', 'Availability', 'Testing of recovery plan procedures', 'The entity tests recovery plan procedures supporting system recovery to meet its objectives.', 'corrective', 'medium'),
  ('fc-soc2-c1-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'C1.1', 'Confidentiality', 'Identification and maintenance of confidential information', 'The entity identifies and maintains confidential information to meet the entity''''s objectives related to confidentiality.', 'preventive', 'high'),
  ('fc-soc2-c1-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'C1.2', 'Confidentiality', 'Disposal of confidential information', 'The entity disposes of confidential information to meet the entity''''s objectives related to confidentiality.', 'preventive', 'medium'),
  ('fc-soc2-pi1-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'PI1.1', 'Processing Integrity', 'Quality information over processing objectives', 'The entity obtains or generates, uses, and communicates relevant, quality information regarding the objectives related to processing, including definitions of data processed and product and service specifications, to support the use of products and services.', 'administrative', 'medium'),
  ('fc-soc2-pi1-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'PI1.2', 'Processing Integrity', 'Controls over system inputs', 'The entity implements policies and procedures over system inputs, including controls over completeness and accuracy, to result in products, services, and reporting to meet the entity''''s objectives.', 'preventive', 'medium'),
  ('fc-soc2-pi1-3', '00000000-0000-0000-0000-000000000001', 'soc2', 'PI1.3', 'Processing Integrity', 'Controls over system processing', 'The entity implements policies and procedures over system processing to result in products, services, and reporting to meet the entity''''s objectives.', 'preventive', 'medium'),
  ('fc-soc2-pi1-4', '00000000-0000-0000-0000-000000000001', 'soc2', 'PI1.4', 'Processing Integrity', 'Controls over system output', 'The entity implements policies and procedures to make available or deliver output completely, accurately, and timely in accordance with specifications to meet the entity''''s objectives.', 'preventive', 'medium'),
  ('fc-soc2-pi1-5', '00000000-0000-0000-0000-000000000001', 'soc2', 'PI1.5', 'Processing Integrity', 'Storage of inputs, items in processing and outputs', 'The entity implements policies and procedures to store inputs, items in processing, and outputs completely, accurately, and timely in accordance with system specifications to meet the entity''''s objectives.', 'preventive', 'medium'),
  ('fc-soc2-p1-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'P1.1', 'Privacy', 'Notice of privacy practices', 'The entity provides notice to data subjects about its privacy practices to meet the entity''''s objectives related to privacy, updated and communicated in a timely manner for changes to those practices.', 'administrative', 'high'),
  ('fc-soc2-p2-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'P2.1', 'Privacy', 'Choice and consent', 'The entity communicates choices available regarding the collection, use, retention, disclosure, and disposal of personal information, and obtains consent as required, only for the intended purpose, to meet its privacy objectives.', 'preventive', 'high'),
  ('fc-soc2-p3-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'P3.1', 'Privacy', 'Collection consistent with objectives', 'Personal information is collected consistent with the entity''''s objectives related to privacy.', 'preventive', 'high'),
  ('fc-soc2-p3-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'P3.2', 'Privacy', 'Explicit consent prior to collection', 'For information requiring explicit consent, the entity communicates the need for such consent and the consequences of failing to provide it, and obtains consent prior to the collection of the information to meet its privacy objectives.', 'preventive', 'medium'),
  ('fc-soc2-p4-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'P4.1', 'Privacy', 'Use limited to identified purposes', 'The entity limits the use of personal information to the purposes identified in the entity''''s objectives related to privacy.', 'preventive', 'high'),
  ('fc-soc2-p4-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'P4.2', 'Privacy', 'Retention of personal information', 'The entity retains personal information consistent with the entity''''s objectives related to privacy.', 'preventive', 'medium'),
  ('fc-soc2-p4-3', '00000000-0000-0000-0000-000000000001', 'soc2', 'P4.3', 'Privacy', 'Secure disposal of personal information', 'The entity securely disposes of personal information to meet the entity''''s objectives related to privacy.', 'preventive', 'medium'),
  ('fc-soc2-p5-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'P5.1', 'Privacy', 'Access by data subjects', 'The entity grants identified and authenticated data subjects the ability to access their stored personal information for review and, upon request, provides copies of that information, informing subjects of any denial and its reason.', 'preventive', 'medium'),
  ('fc-soc2-p5-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'P5.2', 'Privacy', 'Correction of personal information', 'The entity corrects, amends, or appends personal information based on information provided by data subjects and communicates such information to third parties as committed or required, informing subjects of any denial and its reason.', 'corrective', 'medium'),
  ('fc-soc2-p6-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'P6.1', 'Privacy', 'Disclosure with consent', 'The entity discloses personal information to third parties with the explicit consent of data subjects, obtained prior to disclosure, to meet its privacy objectives.', 'preventive', 'high'),
  ('fc-soc2-p6-2', '00000000-0000-0000-0000-000000000001', 'soc2', 'P6.2', 'Privacy', 'Record of authorized disclosures', 'The entity creates and retains a complete, accurate, and timely record of authorized disclosures of personal information to meet the entity''''s objectives related to privacy.', 'detective', 'medium'),
  ('fc-soc2-p6-3', '00000000-0000-0000-0000-000000000001', 'soc2', 'P6.3', 'Privacy', 'Record of unauthorized disclosures', 'The entity creates and retains a complete, accurate, and timely record of detected or reported unauthorized disclosures (including breaches) of personal information to meet its privacy objectives.', 'detective', 'medium'),
  ('fc-soc2-p6-4', '00000000-0000-0000-0000-000000000001', 'soc2', 'P6.4', 'Privacy', 'Privacy commitments from vendors', 'The entity obtains privacy commitments from vendors and other third parties who have access to personal information, assesses their compliance periodically and as needed, and takes corrective action if necessary.', 'administrative', 'high'),
  ('fc-soc2-p6-5', '00000000-0000-0000-0000-000000000001', 'soc2', 'P6.5', 'Privacy', 'Vendor breach notification commitments', 'The entity obtains commitments from vendors and third parties with access to personal information to notify it of actual or suspected unauthorized disclosures, which are reported to appropriate personnel and acted on per incident response procedures.', 'detective', 'medium'),
  ('fc-soc2-p6-6', '00000000-0000-0000-0000-000000000001', 'soc2', 'P6.6', 'Privacy', 'Notification of breaches and incidents', 'The entity provides notification of breaches and incidents to affected data subjects, regulators, and others to meet the entity''''s objectives related to privacy.', 'corrective', 'high'),
  ('fc-soc2-p6-7', '00000000-0000-0000-0000-000000000001', 'soc2', 'P6.7', 'Privacy', 'Accounting of disclosures', 'The entity provides data subjects with an accounting of the personal information held and disclosure of their personal information, upon request, to meet its privacy objectives.', 'administrative', 'low'),
  ('fc-soc2-p7-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'P7.1', 'Privacy', 'Quality of personal information', 'The entity collects and maintains accurate, up-to-date, complete, and relevant personal information to meet the entity''''s objectives related to privacy.', 'preventive', 'medium'),
  ('fc-soc2-p8-1', '00000000-0000-0000-0000-000000000001', 'soc2', 'P8.1', 'Privacy', 'Monitoring and enforcement', 'The entity implements a process for receiving, addressing, resolving, and communicating the resolution of inquiries, complaints, and disputes, monitors compliance periodically, and takes corrective action for identified deficiencies in a timely manner.', 'corrective', 'medium')
INSERT INTO public.framework_controls
  (id, org_id, framework_id, control_ref, domain, title, description, control_type, priority)
VALUES
  ('fc-iso-27001-a-5-1', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.1', 'Organizational Controls', 'Policies for information security', 'Information security policy and topic-specific policies shall be defined, approved by management, published, communicated to and acknowledged by relevant personnel and interested parties, and reviewed at planned intervals and if significant changes occur.', 'governance', 'high'),
  ('fc-iso-27001-a-5-2', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.2', 'Organizational Controls', 'Information security roles and responsibilities', 'Information security roles and responsibilities shall be defined and allocated according to the organization needs.', 'governance', 'high'),
  ('fc-iso-27001-a-5-3', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.3', 'Organizational Controls', 'Segregation of duties', 'Conflicting duties and conflicting areas of responsibility shall be segregated.', 'preventive', 'medium'),
  ('fc-iso-27001-a-5-4', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.4', 'Organizational Controls', 'Management responsibilities', 'Management shall require all personnel to apply information security in accordance with the established information security policy, topic-specific policies and procedures of the organization.', 'governance', 'medium'),
  ('fc-iso-27001-a-5-5', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.5', 'Organizational Controls', 'Contact with authorities', 'The organization shall establish and maintain contact with relevant authorities.', 'administrative', 'medium'),
  ('fc-iso-27001-a-5-6', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.6', 'Organizational Controls', 'Contact with special interest groups', 'The organization shall establish and maintain contact with special interest groups or other specialist security forums and professional associations.', 'administrative', 'low'),
  ('fc-iso-27001-a-5-7', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.7', 'Organizational Controls', 'Threat intelligence', 'Information relating to information security threats shall be collected and analysed to produce threat intelligence.', 'detective', 'medium'),
  ('fc-iso-27001-a-5-8', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.8', 'Organizational Controls', 'Information security in project management', 'Information security shall be integrated into project management.', 'governance', 'medium'),
  ('fc-iso-27001-a-5-9', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.9', 'Organizational Controls', 'Inventory of information and other associated assets', 'An inventory of information and other associated assets, including owners, shall be developed and maintained.', 'administrative', 'high'),
  ('fc-iso-27001-a-5-10', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.10', 'Organizational Controls', 'Acceptable use of information and other associated assets', 'Rules for the acceptable use and procedures for handling information and other associated assets shall be identified, documented and implemented.', 'preventive', 'medium'),
  ('fc-iso-27001-a-5-11', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.11', 'Organizational Controls', 'Return of assets', 'Personnel and other interested parties as appropriate shall return all the organization assets in their possession upon change or termination of their employment, contract or agreement.', 'preventive', 'medium'),
  ('fc-iso-27001-a-5-12', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.12', 'Organizational Controls', 'Classification of information', 'Information shall be classified according to the information security needs of the organization based on confidentiality, integrity, availability and relevant interested party requirements.', 'preventive', 'high'),
  ('fc-iso-27001-a-5-13', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.13', 'Organizational Controls', 'Labelling of information', 'An appropriate set of procedures for information labelling shall be developed and implemented in accordance with the information classification scheme adopted by the organization.', 'preventive', 'medium'),
  ('fc-iso-27001-a-5-14', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.14', 'Organizational Controls', 'Information transfer', 'Information transfer rules, procedures, or agreements shall be in place for all types of transfer facilities within the organization and between the organization and other parties.', 'preventive', 'high'),
  ('fc-iso-27001-a-5-15', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.15', 'Organizational Controls', 'Access control', 'Rules to control physical and logical access to information and other associated assets shall be established and implemented based on business and information security requirements.', 'preventive', 'high'),
  ('fc-iso-27001-a-5-16', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.16', 'Organizational Controls', 'Identity management', 'The full life cycle of identities shall be managed.', 'preventive', 'high'),
  ('fc-iso-27001-a-5-17', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.17', 'Organizational Controls', 'Authentication information', 'Allocation and management of authentication information shall be controlled by a management process, including advising personnel on appropriate handling of authentication information.', 'preventive', 'high'),
  ('fc-iso-27001-a-5-18', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.18', 'Organizational Controls', 'Access rights', 'Access rights to information and other associated assets shall be provisioned, reviewed, modified and removed in accordance with the organization topic-specific policy on and rules for access control.', 'preventive', 'high'),
  ('fc-iso-27001-a-5-19', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.19', 'Organizational Controls', 'Information security in supplier relationships', 'Processes and procedures shall be defined and implemented to manage the information security risks associated with the use of supplier products or services.', 'administrative', 'high'),
  ('fc-iso-27001-a-5-20', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.20', 'Organizational Controls', 'Addressing information security within supplier agreements', 'Relevant information security requirements shall be established and agreed with each supplier based on the type of supplier relationship.', 'administrative', 'medium'),
  ('fc-iso-27001-a-5-21', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.21', 'Organizational Controls', 'Managing information security in the ICT supply chain', 'Processes and procedures shall be defined and implemented to manage the information security risks associated with the ICT products and services supply chain.', 'administrative', 'medium'),
  ('fc-iso-27001-a-5-22', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.22', 'Organizational Controls', 'Monitoring, review and change management of supplier services', 'The organization shall regularly monitor, review, evaluate and manage change in supplier information security practices and service delivery.', 'detective', 'medium'),
  ('fc-iso-27001-a-5-23', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.23', 'Organizational Controls', 'Information security for use of cloud services', 'Processes for acquisition, use, management and exit from cloud services shall be established in accordance with the organization information security requirements.', 'preventive', 'high'),
  ('fc-iso-27001-a-5-24', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.24', 'Organizational Controls', 'Information security incident management planning and preparation', 'The organization shall plan and prepare for managing information security incidents by defining, establishing and communicating information security incident management processes, roles and responsibilities.', 'corrective', 'high'),
  ('fc-iso-27001-a-5-25', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.25', 'Organizational Controls', 'Assessment and decision on information security events', 'The organization shall assess information security events and decide if they are to be categorized as information security incidents.', 'detective', 'medium'),
  ('fc-iso-27001-a-5-26', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.26', 'Organizational Controls', 'Response to information security incidents', 'Information security incidents shall be responded to in accordance with the documented procedures.', 'corrective', 'high'),
  ('fc-iso-27001-a-5-27', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.27', 'Organizational Controls', 'Learning from information security incidents', 'Knowledge gained from information security incidents shall be used to strengthen and improve the information security controls.', 'corrective', 'medium'),
  ('fc-iso-27001-a-5-28', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.28', 'Organizational Controls', 'Collection of evidence', 'The organization shall establish and implement procedures for the identification, collection, acquisition and preservation of evidence related to information security events.', 'detective', 'medium'),
  ('fc-iso-27001-a-5-29', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.29', 'Organizational Controls', 'Information security during disruption', 'The organization shall plan how to maintain information security at an appropriate level during disruption.', 'corrective', 'high'),
  ('fc-iso-27001-a-5-30', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.30', 'Organizational Controls', 'ICT readiness for business continuity', 'ICT readiness shall be planned, implemented, maintained and tested based on business continuity objectives and ICT continuity requirements.', 'corrective', 'high'),
  ('fc-iso-27001-a-5-31', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.31', 'Organizational Controls', 'Legal, statutory, regulatory and contractual requirements', 'Legal, statutory, regulatory and contractual requirements relevant to information security and the organization approach to meet these requirements shall be identified, documented and kept up to date.', 'governance', 'high'),
  ('fc-iso-27001-a-5-32', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.32', 'Organizational Controls', 'Intellectual property rights', 'The organization shall implement appropriate procedures to protect intellectual property rights.', 'preventive', 'medium'),
  ('fc-iso-27001-a-5-33', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.33', 'Organizational Controls', 'Protection of records', 'Records shall be protected from loss, destruction, falsification, unauthorized access and unauthorized release.', 'preventive', 'medium'),
  ('fc-iso-27001-a-5-34', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.34', 'Organizational Controls', 'Privacy and protection of personal identifiable information (PII)', 'The organization shall identify and meet the requirements regarding the preservation of privacy and protection of PII according to applicable laws and regulations and contractual requirements.', 'preventive', 'high'),
  ('fc-iso-27001-a-5-35', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.35', 'Organizational Controls', 'Independent review of information security', 'The organization approach to managing information security and its implementation including people, processes and technologies shall be reviewed independently at planned intervals, or when significant changes occur.', 'detective', 'medium'),
  ('fc-iso-27001-a-5-36', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.36', 'Organizational Controls', 'Compliance with policies, rules and standards for information security', 'Compliance with the organization information security policy, topic-specific policies, rules and standards shall be regularly reviewed.', 'detective', 'medium'),
  ('fc-iso-27001-a-5-37', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.5.37', 'Organizational Controls', 'Documented operating procedures', 'Operating procedures for information processing facilities shall be documented and made available to personnel who need them.', 'administrative', 'medium'),
  ('fc-iso-27001-a-6-1', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.6.1', 'People Controls', 'Screening', 'Background verification checks on all candidates to become personnel shall be carried out prior to joining the organization and on an ongoing basis taking into consideration applicable laws, regulations and ethics and be proportional to the business requirements, the classification of the information to be accessed and the perceived risks.', 'preventive', 'medium'),
  ('fc-iso-27001-a-6-2', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.6.2', 'People Controls', 'Terms and conditions of employment', 'The employment contractual agreements shall state the personnel and the organization responsibilities for information security.', 'preventive', 'medium'),
  ('fc-iso-27001-a-6-3', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.6.3', 'People Controls', 'Information security awareness, education and training', 'Personnel of the organization and relevant interested parties shall receive appropriate information security awareness, education and training and regular updates of the organization information security policy, topic-specific policies and procedures, as relevant for their job function.', 'preventive', 'high'),
  ('fc-iso-27001-a-6-4', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.6.4', 'People Controls', 'Disciplinary process', 'A disciplinary process shall be formalized and communicated to take actions against personnel and other relevant interested parties who have committed an information security policy violation.', 'corrective', 'medium'),
  ('fc-iso-27001-a-6-5', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.6.5', 'People Controls', 'Responsibilities after termination or change of employment', 'Information security responsibilities and duties that remain valid after termination or change of employment shall be defined, enforced and communicated to relevant personnel and other interested parties.', 'preventive', 'medium'),
  ('fc-iso-27001-a-6-6', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.6.6', 'People Controls', 'Confidentiality or non-disclosure agreements', 'Confidentiality or non-disclosure agreements reflecting the organization needs for the protection of information shall be identified, documented, regularly reviewed and signed by personnel and other relevant interested parties.', 'preventive', 'medium'),
  ('fc-iso-27001-a-6-7', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.6.7', 'People Controls', 'Remote working', 'Security measures shall be implemented when personnel are working remotely to protect information accessed, processed or stored outside the organization premises.', 'preventive', 'medium'),
  ('fc-iso-27001-a-6-8', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.6.8', 'People Controls', 'Information security event reporting', 'The organization shall provide a mechanism for personnel to report observed or suspected information security events through appropriate channels in a timely manner.', 'detective', 'medium'),
  ('fc-iso-27001-a-7-1', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.1', 'Physical Controls', 'Physical security perimeters', 'Security perimeters shall be defined and used to protect areas that contain information and other associated assets.', 'physical', 'medium'),
  ('fc-iso-27001-a-7-2', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.2', 'Physical Controls', 'Physical entry', 'Secure areas shall be protected by appropriate entry controls and access points.', 'physical', 'high'),
  ('fc-iso-27001-a-7-3', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.3', 'Physical Controls', 'Securing offices, rooms and facilities', 'Physical security for offices, rooms and facilities shall be designed and implemented.', 'physical', 'medium'),
  ('fc-iso-27001-a-7-4', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.4', 'Physical Controls', 'Physical security monitoring', 'Premises shall be continuously monitored for unauthorized physical access.', 'detective', 'medium'),
  ('fc-iso-27001-a-7-5', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.5', 'Physical Controls', 'Protecting against physical and environmental threats', 'Protection against physical and environmental threats, such as natural disasters and other intentional or unintentional physical threats to infrastructure shall be designed and implemented.', 'physical', 'medium'),
  ('fc-iso-27001-a-7-6', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.6', 'Physical Controls', 'Working in secure areas', 'Security measures for working in secure areas shall be designed and implemented.', 'physical', 'low'),
  ('fc-iso-27001-a-7-7', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.7', 'Physical Controls', 'Clear desk and clear screen', 'Clear desk rules for papers and removable storage media and clear screen rules for information processing facilities shall be defined and appropriately enforced.', 'preventive', 'low'),
  ('fc-iso-27001-a-7-8', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.8', 'Physical Controls', 'Equipment siting and protection', 'Equipment shall be sited securely and protected.', 'physical', 'medium'),
  ('fc-iso-27001-a-7-9', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.9', 'Physical Controls', 'Security of assets off-premises', 'Off-site assets shall be protected.', 'physical', 'medium'),
  ('fc-iso-27001-a-7-10', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.10', 'Physical Controls', 'Storage media', 'Storage media shall be managed through their life cycle of acquisition, use, transportation and disposal in accordance with the organization classification scheme and handling requirements.', 'preventive', 'medium'),
  ('fc-iso-27001-a-7-11', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.11', 'Physical Controls', 'Supporting utilities', 'Information processing facilities shall be protected from power failures and other disruptions caused by failures in supporting utilities.', 'physical', 'medium'),
  ('fc-iso-27001-a-7-12', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.12', 'Physical Controls', 'Cabling security', 'Cables carrying power, data or supporting information services shall be protected from interception, interference or damage.', 'physical', 'low'),
  ('fc-iso-27001-a-7-13', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.13', 'Physical Controls', 'Equipment maintenance', 'Equipment shall be maintained correctly to ensure availability, integrity and confidentiality of information.', 'preventive', 'medium'),
  ('fc-iso-27001-a-7-14', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.7.14', 'Physical Controls', 'Secure disposal or re-use of equipment', 'Items of equipment containing storage media shall be verified to ensure that any sensitive data and licensed software has been removed or securely overwritten prior to disposal or re-use.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-1', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.1', 'Technological Controls', 'User endpoint devices', 'Information stored on, processed by or accessible via user endpoint devices shall be protected.', 'technical', 'high'),
  ('fc-iso-27001-a-8-2', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.2', 'Technological Controls', 'Privileged access rights', 'The allocation and use of privileged access rights shall be restricted and managed.', 'preventive', 'high'),
  ('fc-iso-27001-a-8-3', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.3', 'Technological Controls', 'Information access restriction', 'Access to information and other associated assets shall be restricted in accordance with the established topic-specific policy on access control.', 'preventive', 'high'),
  ('fc-iso-27001-a-8-4', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.4', 'Technological Controls', 'Access to source code', 'Read and write access to source code, development tools and software libraries shall be appropriately managed.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-5', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.5', 'Technological Controls', 'Secure authentication', 'Secure authentication technologies and procedures shall be implemented based on information access restrictions and the topic-specific policy on access control.', 'technical', 'high'),
  ('fc-iso-27001-a-8-6', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.6', 'Technological Controls', 'Capacity management', 'The use of resources shall be monitored and adjusted in line with current and expected capacity requirements.', 'detective', 'medium'),
  ('fc-iso-27001-a-8-7', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.7', 'Technological Controls', 'Protection against malware', 'Protection against malware shall be implemented and supported by appropriate user awareness.', 'preventive', 'high'),
  ('fc-iso-27001-a-8-8', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.8', 'Technological Controls', 'Management of technical vulnerabilities', 'Information about technical vulnerabilities of information systems in use shall be obtained, the organization exposure to such vulnerabilities shall be evaluated and appropriate measures shall be taken.', 'corrective', 'high'),
  ('fc-iso-27001-a-8-9', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.9', 'Technological Controls', 'Configuration management', 'Configurations, including security configurations, of hardware, software, services and networks shall be established, documented, implemented, monitored and reviewed.', 'preventive', 'high'),
  ('fc-iso-27001-a-8-10', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.10', 'Technological Controls', 'Information deletion', 'Information stored in information systems, devices or in any other storage media shall be deleted when no longer required.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-11', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.11', 'Technological Controls', 'Data masking', 'Data masking shall be used in accordance with the organization topic-specific policy on access control and other related topic-specific policies, and business requirements, taking applicable legislation into consideration.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-12', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.12', 'Technological Controls', 'Data leakage prevention', 'Data leakage prevention measures shall be applied to systems, networks and any other devices that process, store or transmit sensitive information.', 'preventive', 'high'),
  ('fc-iso-27001-a-8-13', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.13', 'Technological Controls', 'Information backup', 'Backup copies of information, software and systems shall be maintained and regularly tested in accordance with the agreed topic-specific policy on backup.', 'corrective', 'high'),
  ('fc-iso-27001-a-8-14', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.14', 'Technological Controls', 'Redundancy of information processing facilities', 'Information processing facilities shall be implemented with redundancy sufficient to meet availability requirements.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-15', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.15', 'Technological Controls', 'Logging', 'Logs that record activities, exceptions, faults and other relevant events shall be produced, stored, protected and analysed.', 'detective', 'high'),
  ('fc-iso-27001-a-8-16', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.16', 'Technological Controls', 'Monitoring activities', 'Networks, systems and applications shall be monitored for anomalous behaviour and appropriate actions taken to evaluate potential information security incidents.', 'detective', 'high'),
  ('fc-iso-27001-a-8-17', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.17', 'Technological Controls', 'Clock synchronization', 'The clocks of information processing systems used by the organization shall be synchronized to approved time sources.', 'technical', 'low'),
  ('fc-iso-27001-a-8-18', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.18', 'Technological Controls', 'Use of privileged utility programs', 'The use of utility programs that can be capable of overriding system and application controls shall be restricted and tightly controlled.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-19', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.19', 'Technological Controls', 'Installation of software on operational systems', 'Procedures and measures shall be implemented to securely manage software installation on operational systems.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-20', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.20', 'Technological Controls', 'Networks security', 'Networks and network devices shall be secured, managed and controlled to protect information in systems and applications.', 'technical', 'high'),
  ('fc-iso-27001-a-8-21', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.21', 'Technological Controls', 'Security of network services', 'Security mechanisms, service levels and service requirements of network services shall be identified, implemented and monitored.', 'technical', 'medium'),
  ('fc-iso-27001-a-8-22', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.22', 'Technological Controls', 'Segregation of networks', 'Groups of information services, users and information systems shall be segregated in the organization networks.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-23', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.23', 'Technological Controls', 'Web filtering', 'Access to external websites shall be managed to reduce exposure to malicious content.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-24', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.24', 'Technological Controls', 'Use of cryptography', 'Rules for the effective use of cryptography, including cryptographic key management, shall be defined and implemented.', 'technical', 'high'),
  ('fc-iso-27001-a-8-25', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.25', 'Technological Controls', 'Secure development life cycle', 'Rules for the secure development of software and systems shall be established and applied.', 'preventive', 'high'),
  ('fc-iso-27001-a-8-26', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.26', 'Technological Controls', 'Application security requirements', 'Information security requirements shall be identified, specified and approved when developing or acquiring applications.', 'preventive', 'high'),
  ('fc-iso-27001-a-8-27', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.27', 'Technological Controls', 'Secure system architecture and engineering principles', 'Principles for engineering secure systems shall be established, documented, maintained and applied to any information system development activities.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-28', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.28', 'Technological Controls', 'Secure coding', 'Secure coding principles shall be applied to software development.', 'preventive', 'high'),
  ('fc-iso-27001-a-8-29', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.29', 'Technological Controls', 'Security testing in development and acceptance', 'Security testing processes shall be defined and implemented in the development life cycle.', 'detective', 'high'),
  ('fc-iso-27001-a-8-30', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.30', 'Technological Controls', 'Outsourced development', 'The organization shall direct, monitor and review the activities related to outsourced system development.', 'administrative', 'medium'),
  ('fc-iso-27001-a-8-31', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.31', 'Technological Controls', 'Separation of development, test and production environments', 'Development, testing and production environments shall be separated and secured.', 'preventive', 'high'),
  ('fc-iso-27001-a-8-32', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.32', 'Technological Controls', 'Change management', 'Changes to information processing facilities and information systems shall be subject to change management procedures.', 'preventive', 'high'),
  ('fc-iso-27001-a-8-33', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.33', 'Technological Controls', 'Test information', 'Test information shall be appropriately selected, protected and managed.', 'preventive', 'medium'),
  ('fc-iso-27001-a-8-34', '00000000-0000-0000-0000-000000000001', 'iso-27001', 'A.8.34', 'Technological Controls', 'Protection of information systems during audit testing', 'Audit tests and other assurance activities involving assessment of operational systems shall be planned and agreed between the tester and appropriate management.', 'detective', 'low')
